#include <darkangel/ability_prediction.hpp>
#include <darkangel/character_motor.hpp>
#include "../engine/runtime/ability_state.hpp"
#include <cmath>
#include <iostream>
using namespace darkangel;
namespace {
void check(bool b,const char* error){if(!b)throw std::runtime_error(error);}
MotionRequest request(const AbilityPredictionMotion& motion){MotionRequest result;result.action=motion.activation;result.lock=motion.local.movement_lock;const auto& v=motion.local.root.translation;result.root={v[0],v[1],v[2]};return result;}
void test(bool rejected){
    std::vector<AttributeDefinition> schema{{1,"MaxHealth",AttributeKind::Statistic,100,0,1000,0},{2,"Health",AttributeKind::Resource,100,0,1000,1},{3,"Stamina",AttributeKind::Resource,60,0,60,0}};AbilityOwnerHandle identity{{},77,10};AbilityState server(identity,0,schema,2,1);
    InputProfile input;input.id=AssetId::random();auto kit=std::make_shared<CombatKitDefinition>();kit->id=AssetId::random();kit->locomotion_stance=AssetId::random();kit->generation="kit";for(unsigned i=0;i<combat_slot_count;++i){input.actions.push_back({i+1,"combat."+std::to_string(i),InputActionKind::Button});kit->slots[i]={static_cast<CombatSlot>(i),i+1,{}};}
    auto action=std::make_shared<ActionDefinition>();action->id=AssetId::random();action->generation=std::string(64,'a');action->duration=4*action_tick_units;action->loops=1;action->blocks={{1,0,0,4*action_tick_units,ActionBlockKind::MovementLock,"attack"}};
    ActionClipBinding binding;binding.motor_root=true;binding.archive_generation=std::string(64,'b');binding.clip.id=AssetId::random();binding.clip.runtime=AssetId::random();binding.clip.skeleton=AssetId::random();binding.clip.signature=std::string(64,'c');binding.clip.ticks=4;binding.clip.joints=1;binding.clip.root={{0,0,0,0},{0,0,.2f,0},{0,0,.4f,0},{0,0,.6f,0},{0,0,.8f,0}};action->motion=binding;
    auto ability=std::make_shared<AbilityDefinition>();ability->id=AssetId::random();ability->generation=std::string(64,'d');ability->action=action;ability->costs={{3,20}};kit->slots[0].ability=ability->id;std::array<std::shared_ptr<const AbilityDefinition>,1> catalogue{ability};server.equip(kit,input,catalogue);OwnerAbilityPrediction predicted(server.snapshot(),schema,kit,input,catalogue);
    PhysicsWorld authoritative;PhysicsWorld world(PhysicsWorld::Mode::Prediction);CollisionBox ground{1,{0,-.5,0},{10,.5,10}},wall{2,{0,1,.55},{1,1,.1}};for(auto* physics:{&authoritative,&world}){physics->add(ground);physics->add(wall);}CharacterMotor host(authoritative,{0,0,0},10),motor(world,{0,0,0},10);OwnerPrediction owner(world,motor);CollisionHistory history;history.retain(authoritative.capture());MotorState baseline;AbilityOwnerSnapshot ability_baseline;std::vector<MotorInput> semantic;
    for(unsigned tick=1;tick<=3;++tick){MotorInput command{tick,tick,1};semantic.push_back(command);std::vector<AbilityPredictionInput> operations;if(tick==1)operations.push_back({{10,1,1,1,1,CombatSlot::Light,InputEdge::Pressed,false,false}});auto motion=predicted.advance(tick,operations);owner.predict(command,request(motion));world.step();motor.post_physics();world.finish_tick();
        server.begin_tick(tick);if(tick==1)server.request_wire(operations[0].intent,rejected?std::optional<AbilityFailure>(AbilityFailure::Resources):std::nullopt);server.finish_tick(action_tick_units,false);MotionRequest host_request;if(!rejected)host_request=request(motion);host.step(command,host_request);authoritative.step();host.post_physics();authoritative.finish_tick();history.retain(authoritative.capture());if(tick==1){baseline=host.state();ability_baseline=server.snapshot();}
    }
    check(motor.state().position.z>0&&motor.state().position.z<.4,"Prediction roots are achieved through real Jolt wall collision");auto current_world=authoritative.capture();auto prepared=predicted;prepared.reconcile(ability_baseline);std::vector<MotorCommand> regenerated;for(const auto& motion:prepared.replay_motion())regenerated.push_back({semantic.at(motion.tick-1),request(motion)});
    check(owner.reconcile(baseline,history,regenerated)==ReplayResult::Applied,"Delayed atomic root/motor correction replays disposable collision history");predicted=std::move(prepared);check(std::abs(motor.state().position.z-host.state().position.z)<1e-5&&owner.pending()==2,"Recomputed motor matches accepted/rejected server path");check(predicted.view().attributes[2].value==(rejected?60:40)&&bool(predicted.view().active)==!rejected,"Ability resources and action publish with corrected motor");check(authoritative.tick()==current_world.tick&&authoritative.capture().actors[0].foot==current_world.actors[0].foot,"Owner replay never rewinds or mutates the live authoritative world");
    auto before=motor.state();regenerated[0].input.z=.5;check(owner.reconcile(baseline,history,regenerated)==ReplayResult::Invalid&&motor.state().position==before.position&&owner.needs_resync(),"Mismatched regenerated semantic input fails without partial motor publication");
}
}
int main(){try{test(false);test(true);std::cout<<"Delayed owner ability acceptance/rejection, collision-achieved roots and atomic disposable Jolt motor replay passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
